toolArgs.file_text:
.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

/* Channel Sidebar */
::deep .channel-sidebar {
    width: 20%;
    min-width: 200px;
    background: #2c2f33;
    color: #dcddde;
    display: flex;
    flex-direction: column;
    border-right: 1px solid #202225;
}

::deep .sidebar-header {
    padding: 16px;
    border-bottom: 1px solid #202225;
}

::deep .sidebar-header h3 {
    margin: 0;
    color: #fff;
    font-size: 1rem;
}

::deep .channel-list {
    flex: 1;
    overflow-y: auto;
    padding: 8px 0;
}

::deep .channel-item {
    padding: 8px 16px;
    cursor: pointer;
    position: relative;
    transition: background 0.15s;
}

::deep .channel-item:hover {
    background: #36393f;
}

::deep .channel-item.active {
    background: #393c43;
    border-left: 3px solid #5865f2;
}

::deep .channel-name {
    font-weight: 600;
    font-size: 0.9rem;
    color: #fff;
}

::deep .channel-description {
    font-size: 0.75rem;
    color: #8e9297;
    margin-top: 2px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

::deep .unread-badge {
    position: absolute;
    right: 12px;
    top: 50%;
    transform: translateY(-50%);
    background: #ed4245;
    color: #fff;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 2px 6px;
    border-radius: 10px;
    min-width: 18px;
    text-align: center;
}

/* Main message area */
.chat-main {
    flex: 1;
    display: flex;
    min-width: 0;
}

.chat-main.with-thread {
    flex: 0 0 55%;
}

::deep .message-area {
    flex: 1;
    display: flex;
    flex-direction: column;
    background: #36393f;
    min-width: 0;
}

::deep .message-area-header {
    padding: 12px 20px;
    border-bottom: 1px solid #202225;
    background: #36393f;
}

::deep .message-area-header h2 {
    margin: 0;
    font-size: 1.1rem;
    color: #fff;
}

::deep .message-area-header p {
    margin: 4px 0 0;
    font-size: 0.8rem;
    color: #8e9297;
}

/* Message list */
::deep .message-list {
    flex: 1;
    overflow-y: auto;
    padding: 16px 20px;
}

::deep .loading-indicator {
    text-align: center;
    color: #8e9297;
    padding: 8px;
    font-size: 0.85rem;
}

::deep .message-bubble {
    padding: 8px 12px;
    margin-bottom: 4px;
    border-radius: 4px;
    position: relative;
    transition: background 0.1s;
}

::deep .message-bubble:hover {
    background: #32353b;
}

::deep .message-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 4px;
}

::deep .message-header .author {
    font-weight: 600;
    color: #fff;
    font-size: 0.9rem;
}

::deep .message-header .timestamp {
    font-size: 0.7rem;
    color: #72767d;
}

::deep .message-content {
    color: #dcddde;
    font-size: 0.9rem;
    line-height: 1.4;
    word-wrap: break-word;
}

/* Reactions */
::deep .reactions {
    display: flex;
    flex-wrap: wrap;
    gap: 4px;
    margin-top: 6px;
}

::deep .reaction-badge {
    background: #2f3136;
    border: 1px solid #4f545c;
    border-radius: 4px;
    padding: 2px 6px;
    font-size: 0.8rem;
    cursor: pointer;
    color: #dcddde;
    transition: background 0.15s;
}

::deep .reaction-badge:hover {
    background: #5865f2;
    border-color: #5865f2;
}

/* Thread link */
::deep .thread-link {
    margin-top: 4px;
    font-size: 0.8rem;
    color: #5865f2;
    cursor: pointer;
    font-weight: 500;
}

::deep .thread-link:hover {
    text-decoration: underline;
}

/* Message actions (hover toolbar) */
::deep .message-actions {
    position: absolute;
    top: -12px;
    right: 12px;
    background: #2f3136;
    border: 1px solid #4f545c;
    border-radius: 4px;
    display: flex;
    gap: 2px;
    padding: 2px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.3);
}

::deep .action-btn {
    background: none;
    border: none;
    color: #b9bbbe;
    cursor: pointer;
    padding: 4px 8px;
    font-size: 0.75rem;
    border-radius: 3px;
    transition: background 0.1s, color 0.1s;
}

::deep .action-btn:hover {
    background: #4f545c;
